export function initAtlasFeed({db,esc,date,getArticles,openNews,goHome,goLetters,goPolls}){
 const root=document.getElementById('atlas-feed');let kind='all',limit=40,rows=[],loading=false,error='',uid=null;
 const safe=esc;
 root.innerHTML='<div class="heading"><div><span class="eyebrow">COMUNIDAD / ATLAS</span><h1>Feed</h1><p>Lo que la comunidad comparte en Atlas.</p></div><button id="atlas-feed-refresh">↻ Actualizar</button></div><div class="atlas-feed-tabs" role="group" aria-label="Filtrar publicaciones"><button data-atlas-kind="all" aria-pressed="true">Todo</button><button data-atlas-kind="comment" aria-pressed="false">Conversaciones</button><button data-atlas-kind="letter" aria-pressed="false">Cartas</button><button data-atlas-kind="poll" aria-pressed="false">Encuestas</button></div><p id="atlas-feed-status" role="status"></p><div id="atlas-feed-list"></div>';
 const $=id=>root.querySelector('#'+id);
 function render(){const list=rows.filter(r=>kind==='all'||r.kind===kind).slice(0,limit);$('atlas-feed-list').innerHTML=list.map(r=>{if(r.kind==='comment')return '<article class="atlas-share-card"><span class="eyebrow">CONVERSACIÓN EN NOTICIAS</span><p class="atlas-share-quote">'+safe(r.body)+'</p><p class="atlas-share-author">'+safe(r.author)+' · '+safe(date(r.created_at))+'</p><button data-open-news="'+safe(r.article_id)+'" class="text-link">'+safe(r.articleTitle||'Abrir noticia relacionada')+' ↗</button></article>';if(r.kind==='letter')return '<article class="atlas-share-card"><span class="eyebrow">CARTA AL DIRECTOR</span><h2>'+safe(r.title)+'</h2><p class="atlas-share-author">'+safe(r.signature)+' · '+safe(date(r.created_at))+'</p><p class="atlas-share-quote">'+safe(r.body)+'</p><button data-open-letters class="text-link">Ver cartas al director ↗</button></article>';return '<article class="atlas-share-card"><span class="eyebrow">ENCUESTA · '+safe(r.topic)+'</span><h2>'+safe(r.title)+'</h2><p>'+safe(r.description||'Encuesta publicada en Atlas. Participación voluntaria.')+'</p><p class="atlas-share-author">Publicada '+safe(date(r.created_at))+' · '+(new Date(r.closes_at).getTime()>Date.now()?'Abierta':'Cerrada')+'</p><button data-open-polls class="text-link">Ver resultados y participar ↗</button></article>';}).join('')||'<div class="panel"><p>'+(loading?'Cargando publicaciones…':error?'No se pudo actualizar el Feed. Intenta de nuevo.':'Todavía no hay publicaciones en esta categoría.')+'</p></div>';
 root.querySelectorAll('[data-open-news]').forEach(b=>b.onclick=()=>{const a=(getArticles()||[]).find(x=>x.id===b.dataset.openNews||x.id==='news:'+b.dataset.openNews);if(a)openNews(a);else goHome();});root.querySelector('[data-open-letters]')?.addEventListener('click',goLetters);root.querySelectorAll('[data-open-polls]').forEach(b=>b.onclick=goPolls);
 }
 async function refresh(){if(loading)return;loading=true;error='';$('atlas-feed-status').textContent='Actualizando el Feed…';render();try{if(!db)throw Error();const [comments,letters,polls]=await Promise.all([db.from('atlas_dev_news_comments').select('article_id,author_name,body,created_at').order('created_at',{ascending:false}).limit(60),db.from('atlas_dev_letters').select('title,body,signature,created_at').order('created_at',{ascending:false}).limit(30),db.from('atlas_dev_polls').select('id,title,description,topic,created_at,closes_at,closed,archived').eq('archived',false).order('created_at',{ascending:false}).limit(30)]);if(comments.error||letters.error||polls.error)throw Error();const articles=getArticles()||[],byId=new Map(articles.flatMap(a=>[[a.id,a],[a.id.replace(/^news:/,''),a]]));rows=[...comments.data.map(r=>({...r,kind:'comment',author:r.author_name,articleTitle:byId.get(r.article_id)?.title})).filter(r=>r.body),...letters.data.map(r=>({...r,kind:'letter'})),...polls.data.filter(p=>!p.archived).map(r=>({...r,kind:'poll'}))].sort((a,b)=>Date.parse(b.created_at)-Date.parse(a.created_at));$('atlas-feed-status').textContent=rows.length+' publicaciones y conversaciones de Atlas.';}catch{error='load';$('atlas-feed-status').textContent=rows.length?'No se pudo actualizar. Se conserva la consulta anterior.':'No se pudo conectar con el Feed.';}finally{loading=false;render();}}
 root.querySelectorAll('[data-atlas-kind]').forEach(b=>b.onclick=()=>{kind=b.dataset.atlasKind;limit=40;root.querySelectorAll('[data-atlas-kind]').forEach(x=>{x.setAttribute('aria-pressed',String(x===b));x.classList.toggle('active',x===b)});render();});$('atlas-feed-refresh').onclick=refresh;db?.auth.onAuthStateChange((_e,s)=>{uid=s?.user?.id||null;});refresh();return {refresh};
}
